CREATE TABLE tantu.calendar_preferences(workspace_id uuid NOT NULL REFERENCES tantu.workspaces,user_id uuid NOT NULL REFERENCES tantu.users,timezone text NOT NULL,week_start integer NOT NULL CHECK(week_start IN(0,1)),start_hour integer NOT NULL CHECK(start_hour BETWEEN 0 AND 23),end_hour integer NOT NULL CHECK(end_hour BETWEEN 1 AND 24 AND end_hour>start_hour),working_days integer[] NOT NULL DEFAULT '{1,2,3,4,5}',buffer_minutes integer NOT NULL DEFAULT 0 CHECK(buffer_minutes BETWEEN 0 AND 120),density text NOT NULL DEFAULT 'comfortable' CHECK(density IN('compact','comfortable')),connections uuid[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,user_id));
ALTER TABLE tantu.calendar_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE tantu.calendar_preferences FORCE ROW LEVEL SECURITY;
CREATE POLICY calendar_preferences_scope ON tantu.calendar_preferences FOR ALL USING(workspace_id=tantu.tenant() AND user_id=tantu.actor() AND tantu.member_role(workspace_id) IS NOT NULL) WITH CHECK(workspace_id=tantu.tenant() AND user_id=tantu.actor() AND tantu.member_role(workspace_id) IS NOT NULL);
ALTER TABLE tantu.schedule_reviews ADD sources_fingerprint text;
CREATE TABLE tantu.provider_effect_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,connection_id uuid NOT NULL,connection_version integer NOT NULL,request jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes',FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
CREATE TABLE tantu.provider_effects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,connection_id uuid NOT NULL,review_id uuid NOT NULL UNIQUE REFERENCES tantu.provider_effect_reviews,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','unknown','confirmed','failed','cancelled')),provider_id text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
ALTER TABLE tantu.provider_effect_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE tantu.provider_effect_reviews FORCE ROW LEVEL SECURITY;
CREATE POLICY effect_review_scope ON tantu.provider_effect_reviews FOR ALL USING(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id)) WITH CHECK(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id));
ALTER TABLE tantu.provider_effects ENABLE ROW LEVEL SECURITY;
ALTER TABLE tantu.provider_effects FORCE ROW LEVEL SECURITY;
CREATE POLICY effect_scope ON tantu.provider_effects FOR ALL USING(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id)) WITH CHECK(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id));
